//! Control contract data.
//!
//! the embedded campaign asset is generated by
//! the extraction pipeline from the snapshot's shared sources and is
//! hash-pinned per file.  This module is the typed view the runtime and the
//! focused test use; `--check` fails if the shared sources drifted from the
//! hashes, so the table below cannot silently describe an older dispatch.

const std = @import("std");

pub const schema_id = "suikoden-control-contract/1";

pub const Source = struct {
    path: []const u8,
    sha256: []const u8,
    bytes: u64,
    role: []const u8,
};

pub const Fact = struct {
    id: []const u8,
    file: []const u8,
    line: u32,
    text_hash: []const u8,
    statement: []const u8,
};

pub const Policy = struct {
    retain: []const []const u8,
    clear: []const []const u8,
    until_release: []const []const u8,
};

pub const TransitionFact = struct {
    id: []const u8,
    from: []const u8,
    to: []const u8,
    reason: []const u8,
    /// True when the destination accepts the held movement vector.
    retain_direction: bool,
    /// True when navigation repeats are withheld until the direction releases.
    navigation_until_release: bool,
    /// The boundary frame's one-shot edges are withheld (same-advance menu).
    withhold_same_advance_edges: bool,
};

pub const Unsupported = struct {
    from: []const u8,
    to: []const u8,
    statement: []const u8,
};

pub const Blocker = struct {
    id: []const u8,
    kind: []const u8,
    detail: []const u8,
};

pub const Contract = struct {
    schema: []const u8 = "",
    source: []const Source = &.{},
    owners: []const []const u8 = &.{},
    facts: []const Fact = &.{},
    transitions: []const TransitionFact = &.{},
    unsupported_transitions: []const Unsupported = &.{},
    policy: Policy = .{ .retain = &.{}, .clear = &.{}, .until_release = &.{} },
    blockers: []const Blocker = &.{},

    pub fn load(allocator: std.mem.Allocator, bytes: []const u8) !std.json.Parsed(Contract) {
        const parsed = try std.json.parseFromSlice(Contract, allocator, bytes, .{ .allocate = .alloc_always, .ignore_unknown_fields = true });
        errdefer parsed.deinit();
        if (!std.mem.eql(u8, parsed.value.schema, schema_id)) return error.UnsupportedControlContract;
        if (parsed.value.source.len == 0 or parsed.value.transitions.len == 0) return error.InvalidControlContract;
        return parsed;
    }
};
